<?php
namespace App\Http\Controllers\Api\V1;
use App\Models\{DeliveryOrder,DeliveryOrderItem,SalesOrder,SalesOrderItem,StockReservation,InventoryBalance}; use App\Services\{AuthorizationService,SalesDocumentService,SalesNumberService,StockMovementService}; use App\Support\{Decimal,TenantContext}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
final class DeliveryOrderController { public function store(Request $r,SalesOrder $order,AuthorizationService $a,SalesNumberService $numbers){abort_unless($order->tenant_id===app(TenantContext::class)->id(),404);abort_unless($a->allows($r->user(),$order->tenant_id,'sales.manage'),403);$d=$r->validate(['idempotency_key'=>'required|string|max:100','items'=>'required|array|min:1','items.*.sales_order_item_id'=>'required|uuid','items.*.quantity'=>'required|numeric|min:0.000001']);if($existing=DeliveryOrder::where('tenant_id',$order->tenant_id)->where('idempotency_key',$d['idempotency_key'])->first())return response()->json(['data'=>$existing]);$delivery=DB::transaction(function()use($d,$order,$r,$numbers){$do=DeliveryOrder::create(['tenant_id'=>$order->tenant_id,'sales_order_id'=>$order->id,'created_by'=>$r->user()->id,'number'=>$numbers->next($order->tenant_id,'delivery'),'idempotency_key'=>$d['idempotency_key']]);foreach($d['items'] as $line){$item=SalesOrderItem::where('tenant_id',$order->tenant_id)->where('sales_order_id',$order->id)->whereKey($line['sales_order_item_id'])->lockForUpdate()->firstOrFail();$qty=Decimal::normalize((string)$line['quantity']);$remaining=Decimal::sub((string)$item->reserved_quantity,(string)$item->delivered_quantity);if(Decimal::compare($qty,$remaining)>0)throw ValidationException::withMessages(['quantity'=>['Cannot deliver more than reserved quantity.']]);$reservation=StockReservation::where('tenant_id',$order->tenant_id)->where('sales_order_item_id',$item->id)->where('state','active')->lockForUpdate()->firstOrFail();$balance=InventoryBalance::where('tenant_id',$order->tenant_id)->where('variant_id',$item->variant_id)->where('location_id',$reservation->location_id)->lockForUpdate()->firstOrFail();$balance->update(['reserved_quantity'=>Decimal::sub((string)$balance->reserved_quantity,$qty)]);app(StockMovementService::class)->post(['tenant_id'=>$order->tenant_id,'variant_id'=>$item->variant_id,'location_id'=>$reservation->location_id,'quantity'=>Decimal::sub('0',$qty),'created_by'=>$r->user()->id,'movement_type'=>'sale_delivery','unit_cost'=>'0','reference_type'=>'delivery_order','reference_id'=>$do->id,'idempotency_key'=>'delivery:'.$do->id.':'.$item->id]);$item->update(['delivered_quantity'=>Decimal::add((string)$item->delivered_quantity,$qty)]);$reservation->update(['quantity'=>Decimal::sub((string)$reservation->quantity,$qty,'6'),'state'=>Decimal::compare(Decimal::sub((string)$reservation->quantity,$qty),'0')===0?'consumed':'active']);DeliveryOrderItem::create(['tenant_id'=>$order->tenant_id,'delivery_order_id'=>$do->id,'sales_order_item_id'=>$item->id,'location_id'=>$reservation->location_id,'quantity'=>$qty]);}$do->update(['state'=>'posted','posted_at'=>now()]);return $do->load('items');});return response()->json(['data'=>$delivery],201);} }
